const getSlotIndexForTime = (timeStr?: string) => {
  if (!timeStr) return 2;
  const parts = timeStr.split(":");
  const hour = parseInt(parts[0], 10);
  if (isNaN(hour)) return 2;

  for (let i = TIME_SLOTS.length - 1; i >= 0; i--) {
    if (hour >= TIME_SLOTS[i].startHour) {
      return i;
    }
  }
  return 0;
};

