    events.forEach((e) => {
      csvRows.push(
        `${e.id},"${e.title}",${e.date},${e.time},${e.type},${e.platform}`,
      );
    });
    const blob = new Blob([csvRows.join("\n")], {
      type: "text/csv;charset=utf-8;",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
