    bg: "bg-[#9b8afb] text-white",
    bgSoft: "bg-[#9b8afb]/15 text-[#7a64f7] dark:bg-[#9b8afb]/20 dark:text-[#c4bbfd]",
    hoverBg: "hover:bg-[#9b8afb]/10 hover:text-[#8774f8] dark:hover:text-[#b4a7fc]",
